import math

def transform(scores: dict, graph, question: str, question_date: str) -> dict:
    if not scores:
        return scores

    # Parse turn_id into (session_id, turn_index)
    def parse_turn(turn_id):
        if '#' in turn_id:
            parts = turn_id.rsplit('#', 1)
            try:
                return parts[0], int(parts[1])
            except ValueError:
                return parts[0], 0
        return turn_id, 0

    # Group turns by session
    session_turns = {}
    for turn_id, score in scores.items():
        session_id, turn_idx = parse_turn(turn_id)
        if session_id not in session_turns:
            session_turns[session_id] = []
        session_turns[session_id].append((turn_id, score, turn_idx))

    # Sort turns within each session by score descending
    for session_id in session_turns:
        session_turns[session_id].sort(key=lambda x: x[1], reverse=True)

    # Compute rank within session (0-based, by score)
    turn_session_rank = {}
    for session_id, turns in session_turns.items():
        for rank, (turn_id, score, turn_idx) in enumerate(turns):
            turn_session_rank[turn_id] = rank

    # Count how many sessions there are and their sizes
    num_sessions = len(session_turns)

    # Sort all scores to get global ranks
    sorted_turns = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    global_rank = {turn_id: rank for rank, (turn_id, _) in enumerate(sorted_turns)}

    # Apply diminishing returns penalty based on within-session rank
    # The penalty grows with session rank to promote diversity
    new_scores = {}

    for turn_id, score in scores.items():
        session_id, turn_idx = parse_turn(turn_id)
        s_rank = turn_session_rank[turn_id]
        session_size = len(session_turns[session_id])

        # Diminishing returns: penalize later turns within same session
        # First turn in session: no penalty
        # Subsequent turns: apply decay
        if s_rank == 0:
            penalty = 1.0
        else:
            # Stronger penalty for sessions with many turns
            # Use log-based decay
            penalty = 1.0 / (1.0 + s_rank * 0.5)

        # Additional boost for turns that are the first/only turn in their session
        # This helps evidence from underrepresented sessions
        if session_size == 1:
            diversity_boost = 1.1
        else:
            diversity_boost = 1.0

        # For turns with low absolute scores but potentially important,
        # apply a mild global rank-based adjustment to compress the score range
        # This helps low-ranked evidence compete better
        g_rank = global_rank[turn_id]
        total_turns = len(scores)

        # Compress scores: boost lower-ranked turns slightly, reduce top compression
        # Use sqrt compression on the penalty to soften it
        adjusted_score = score * penalty * diversity_boost

        new_scores[turn_id] = adjusted_score

    return new_scores

import math

def transform(scores: dict, graph, question: str, question_date: str) -> dict:
    if not scores:
        return scores

    # Parse turn_id into (session_id, turn_index)
    def parse_turn(turn_id):
        parts = turn_id.rsplit('#', 1)
        if len(parts) == 2:
            try:
                return parts[0], int(parts[1])
            except ValueError:
                return parts[0], 0
        return turn_id, 0

    # Group turns by session
    session_turns = {}
    for turn_id, score in scores.items():
        session_id, turn_idx = parse_turn(turn_id)
        if session_id not in session_turns:
            session_turns[session_id] = []
        session_turns[session_id].append((turn_id, turn_idx, score))

    # For each session, sort by score descending
    for session_id in session_turns:
        session_turns[session_id].sort(key=lambda x: x[2], reverse=True)

    # Compute session max score
    session_max = {}
    for session_id, turns in session_turns.items():
        session_max[session_id] = max(t[2] for t in turns)

    # Global score stats
    all_scores = list(scores.values())
    max_score = max(all_scores) if all_scores else 1.0
    min_score = min(all_scores) if all_scores else 0.0

    new_scores = {}

    for turn_id, score in scores.items():
        session_id, turn_idx = parse_turn(turn_id)
        turns_in_session = session_turns[session_id]
        n_turns = len(turns_in_session)

        # Find rank of this turn within its session (by score)
        rank_in_session = 0
        for i, (tid, tidx, ts) in enumerate(turns_in_session):
            if tid == turn_id:
                rank_in_session = i
                break

        # Diminishing returns penalty for lower-ranked turns within same session
        # First turn in session keeps full score, subsequent ones get penalized
        diversity_penalty = math.exp(-0.5 * rank_in_session)

        # Boost for early turn indices (turn #0, #1, #2 tend to be evidence)
        if turn_idx == 0:
            position_boost = 1.15
        elif turn_idx <= 2:
            position_boost = 1.05
        elif turn_idx <= 4:
            position_boost = 1.0
        else:
            # Penalize high-index turns slightly
            position_boost = math.exp(-0.03 * (turn_idx - 4))

        # If session has many turns competing, apply stronger diversity penalty
        if n_turns >= 4:
            session_size_factor = math.exp(-0.1 * (n_turns - 3))
        else:
            session_size_factor = 1.0

        # Combined transform
        new_score = score * diversity_penalty * position_boost * session_size_factor

        # Ensure scores stay positive and reasonable
        new_score = max(new_score, score * 0.01)

        new_scores[turn_id] = new_score

    return new_scores
